-- 2. SITE SETTINGS
INSERT OR REPLACE INTO site_settings (id, brand_name, slogan, default_seo_title, default_seo_description, contact_email, notification_email, contact_phone, address, social_links, footer_note, copyright, budget_comparison_message, updated_at) VALUES ('settings_default', 'Wanderer''s Journeys', 'Where curiosity leads, possibilities unfold', 'Wanderer''s Journeys | Live Freely, Retire Happily in Vietnam', 'Turnkey luxury retirement living, seasonal escapes, and exploratory stays in Da Nang, Nha Trang, and Ho Chi Minh City.', 'info@wanderersjourneys.com', 'info@wanderersjourneys.com', '+84 (0) 28 3822 5588', 'Level 18, Saigon Centre Tower 2, 67 Le Loi, District 1, Ho Chi Minh City, Vietnam', '{"facebook":"https://facebook.com/wanderersjourneys","instagram":"https://instagram.com/wanderersjourneys","tiktok":"https://tiktok.com/@wanderersjourneys"}', 'Wanderer’s Journeys provides premium hospitality, lifestyle curation, and residential advisory for international seniors and explorers in Vietnam. Independent legal, visa, and financial services are facilitated through accredited licensed partners.', '© 2026 Wanderer’s Journeys Hospitality Ltd. All rights reserved.', 'Experience premier coastal resort living, daily wellness, and dedicated concierge care in Vietnam for $40,000/year with a standard of living rivaling $90,000+ in North America or Western Europe.', '2026-10-27T14:41:54.123Z');

-- 3. HERO CONTENT
INSERT OR REPLACE INTO hero_content (id, headline, tagline, subtext, primary_cta_text, secondary_cta_text, badge_text, background_image_url, stats, updated_at) VALUES ('hero_default', 'Live Freely, Retire Happily in Vietnam', 'Where curiosity leads, possibilities unfold', 'Discover Westerner Retirement Communities (WRCs) across Vietnam’s most stunning coastal cities and vibrant havens. Fully serviced residences, dedicated English-speaking concierge, healthcare navigation, and vibrant expat fellowship.', 'Request a Bespoke Proposal', 'Explore Living Packages', 'Curated Long-Term Living & Retirement Communities', 'https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=2000&q=80', '[{"label":"Starting Monthly Package","value":"$2,250"},{"label":"Expat Resident Rating","value":"4.9 / 5.0"},{"label":"Concierge & Health Support","value":"24 / 7"},{"label":"Prime Coastal Cities","value":"3 Hubs"}]', '2026-10-31T03:26:22.263Z');

-- 4. WHY VIETNAM
INSERT OR REPLACE INTO why_vietnam (id, title, subtitle, description, highlights, icon, display_order, is_published, created_at, updated_at) VALUES ('wv_cost', 'Remarkable Cost of Living', NULL, 'Enjoy upscale beachfront or city living, fine dining, domestic assistance, and leisurely pursuits at 50% to 65% lower expenses than Western metropolitan centers without compromising safety or luxury.', '[]', 'PiggyBank', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-31T03:26:22.264Z');
INSERT OR REPLACE INTO why_vietnam (id, title, subtitle, description, highlights, icon, display_order, is_published, created_at, updated_at) VALUES ('wv_climate', 'Sun-Drenched Tropical Lifestyle', NULL, 'Escape harsh winters with mild coastal sea breezes, year-round sunshine in Da Nang and Nha Trang, championship golf courses, pristine beaches, and relaxed open-air cafes.', '[]', 'SunMedium', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-31T03:26:22.264Z');
INSERT OR REPLACE INTO why_vietnam (id, title, subtitle, description, highlights, icon, display_order, is_published, created_at, updated_at) VALUES ('wv_culture', 'Warm Hospitality & Safe Society', NULL, 'Vietnam consistently ranks among Southeast Asia’s safest, most welcoming countries. Savor fresh world-renowned cuisine, deep cultural heritage, and genuine warmth from local communities.', '[]', 'HeartHandshake', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-31T03:26:22.264Z');
INSERT OR REPLACE INTO why_vietnam (id, title, subtitle, description, highlights, icon, display_order, is_published, created_at, updated_at) VALUES ('wv_health', 'Modern Healthcare & Wellness', NULL, 'Benefit from JCI-accredited international hospitals, Western-trained physicians, prompt specialist appointments, and comprehensive wellness sanctuaries at fraction of Western out-of-pocket costs.', '[]', 'ShieldCheck', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-31T03:26:22.264Z');

-- 5. WHY CHOOSE US
INSERT OR REPLACE INTO why_choose_us (id, title, description, icon, display_order, is_published) VALUES ('wcu_concierge', 'Dedicated Lifestyle Concierge', 'Every resident is paired with a fluent bilingual personal navigator who coordinates medical visits, bill payments, grocery deliveries, excursions, and daily conveniences.', 'Compass', 1, 1);
INSERT OR REPLACE INTO why_choose_us (id, title, description, icon, display_order, is_published) VALUES ('wcu_transparent', 'Turnkey All-Inclusive Billing', 'One predictable monthly invoice covers accommodation, high-speed fiber internet, housekeeping, utilities allowance, clubhouse access, and lifestyle support.', 'CheckCircle2', 1, 1);
INSERT OR REPLACE INTO why_choose_us (id, title, description, icon, display_order, is_published) VALUES ('wcu_community', 'Thriving Expat Fellowship', 'Regular social mixers, golf outings, book clubs, Vietnamese language workshops, and group culinary tours foster deep friendships from day one.', 'Users2', 1, 1);
INSERT OR REPLACE INTO why_choose_us (id, title, description, icon, display_order, is_published) VALUES ('wcu_flexibility', 'Seasonal Freedom & Fluidity', 'Whether spending 30 days testing the waters, escaping winter as a Snowbird, or putting down 12-month roots, transition seamlessly between our coastal hubs.', 'Anchor', 1, 1);

-- 6. CORE SERVICE
INSERT OR REPLACE INTO core_services (id, title, monthly_starting_price, description, utility_allowance_note, resort_amenities, personal_assistant, cleaning_schedule, internet_speed, visa_support_note, health_insurance_support_note, banking_support_note, display_order, is_published, created_at, updated_at) VALUES ('core_service_main', 'Wanderer’s All-Inclusive Living Inclusions', 2250, 'Every long-term stay is crafted to eliminate life’s mundane burdens so you can focus entirely on enjoying your retirement and passions.', 'Includes monthly allowance up to $150 USD covering electricity, water, and cooling usage.', '["Private Clubhouse Lounge & Expat Library","Resort-Style Saltwater Swimming Pools","State-of-the-Art Fitness Gym & Yoga Pavilion","Tennis & Pickleball Courts (facility-dependent)","24/7 Gated Security & Monitored Access"]', 'Dedicated English-fluent Personal Assistant for appointments, translations, and lifestyle logistics.', 'Professional housekeeping 3 times weekly with linen and towel refresh.', 'High-speed dedicated 100 Mbps fiber-optic Wi-Fi with dual-band mesh coverage.', 'Complimentary advisory, renewal tracking, and processing assistance via accredited visa partners.', 'Direct orientation with international expatriate healthcare brokers and hospital registration.', 'Assistance setting up international debit cards, secure remittance channels, and local utility accounts.', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');

-- 7. ADDITIONAL SERVICES
INSERT OR REPLACE INTO additional_services (id, title, description, price_label, category, icon, conditions, display_order, is_published, created_at, updated_at) VALUES ('as_medical', 'In-Home Medical Care & Visiting Nurse', 'Arrangement of licensed visiting registered nurses for regular vital checks, medication management, and priority physician house calls.', 'From $45 / visit or tailored monthly plan', 'Healthcare & Wellness', 'Stethoscope', 'Provided via licensed partner international clinics in HCMC, Da Nang, and Nha Trang.', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO additional_services (id, title, description, price_label, category, icon, conditions, display_order, is_published, created_at, updated_at) VALUES ('as_chef', 'Private Full-Time Housekeeper & Chef', 'Dedicated culinary expert crafting nutritious dietary-tailored meals, farm-fresh market sourcing, and complete home care.', '$350 - $600 / month', 'Household', 'UtensilsCrossed', 'Vetted background checks, culinary testing, and English conversational basics.', 2, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO additional_services (id, title, description, price_label, category, icon, conditions, display_order, is_published, created_at, updated_at) VALUES ('as_chauffeur', 'Private Chauffeur & VIP Vehicle', 'On-demand airport transfers, weekly shopping excursions, and private day trips in premium air-conditioned sedans or SUVs.', 'Hourly, daily, or $550 / month dedicated', 'Transportation', 'Car', 'Includes fuel, tolls, and licensed experienced English-familiar driver.', 3, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO additional_services (id, title, description, price_label, category, icon, conditions, display_order, is_published, created_at, updated_at) VALUES ('as_tours', 'Bespoke Regional Discovery Tours', 'Exclusive weekend escapes to Hoi An ancient town, Ba Na Hills, Mekong Delta floating markets, and Dalat highlands.', 'Tailored per itinerary', 'Leisure', 'MapPin', 'All-inclusive private guide, luxury transport, and handpicked boutique lodging.', 4, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');

-- 8. PACKAGES
INSERT OR REPLACE INTO packages (id, package_code, title, duration_label, duration_category, target_audience, starting_price_usd, description, ideal_for, inclusions, display_order, is_published, created_at, updated_at) VALUES ('pkg_discovery', NULL, 'Private Discovery Tour', NULL, NULL, NULL, 0, NULL, 'Explorers who want a firsthand test drive before committing to a longer stay.', '["Luxury 5-star or serviced apartment accommodation","Private airport VIP greeting and dedicated chauffeur","Full escorted neighborhood, facility, and clinic walkthroughs","One-on-one consultation with visa & living cost advisors","Hosted dinners with active expat community leaders"]', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO packages (id, package_code, title, duration_label, duration_category, target_audience, starting_price_usd, description, ideal_for, inclusions, display_order, is_published, created_at, updated_at) VALUES ('pkg_trial30', NULL, '30-Day Living Trial', NULL, NULL, NULL, 0, NULL, 'Seniors taking an extended sabbatical or evaluating Vietnam for retirement.', '["Fully furnished 2-bedroom executive residence","Housekeeping 3x weekly with fresh linens","Dedicated Personal Navigator for local orientation","High-speed 100 Mbps internet & utilities allowance ($150)","Clubhouse, fitness center, and swimming pool privileges","Invitations to weekly expat social dinners & excursions"]', 2, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO packages (id, package_code, title, duration_label, duration_category, target_audience, starting_price_usd, description, ideal_for, inclusions, display_order, is_published, created_at, updated_at) VALUES ('pkg_snowbird', NULL, 'Snowbird Special', NULL, NULL, NULL, 0, NULL, 'Retirees who keep a summer home in the West and winter in the tropics.', '["Ocean-view 2-bedroom or luxury garden residence","Complete utility credit ($150/mo) and fiber Wi-Fi","Housekeeping 3x weekly & bi-weekly laundry service","Local healthcare clinic registration & emergency on-call","Seasonal golf league & wellness club passes"]', 3, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO packages (id, package_code, title, duration_label, duration_category, target_audience, starting_price_usd, description, ideal_for, inclusions, display_order, is_published, created_at, updated_at) VALUES ('pkg_exploratory6', NULL, 'Six-Month Exploratory Stay', NULL, NULL, NULL, 0, NULL, 'Independent retirees ready for a substantial international chapter.', '["Turnkey 2-bedroom master suite in premier WRC community","Inter-city transfer assistance between Wanderer’s hubs","Dedicated assistant for personal banking and residency documentation","Comprehensive maintenance, security, and housekeeping","Complimentary weekly conversational Vietnamese lessons"]', 4, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO packages (id, package_code, title, duration_label, duration_category, target_audience, starting_price_usd, description, ideal_for, inclusions, display_order, is_published, created_at, updated_at) VALUES ('pkg_retirement12', NULL, 'Full Retirement Package', NULL, NULL, NULL, 0, NULL, 'Expats seeking worry-free, long-term tropical retirement in luxury.', '["Prime residential residence with guaranteed price protection","Full 24/7 bilingual concierge & on-call health emergency response","Regular preventative health wellness checkups with partner clinic","Housekeeping 3x weekly, deep cleaning quarterly, laundry assistance","VIP access to all Wanderer’s clubhouse amenities & social events","Annual visa renewal coordination and local government registration"]', 5, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');

