INSERT OR REPLACE INTO accommodations (id, title, city, district, neighborhood, room_type, size_sqm, bedrooms, bathrooms, price_month_usd, description, features, nearby_amenities, images, is_flagship, display_order, is_published, created_at, updated_at) VALUES ('acc_sg_01', 'The Thao Dien Botanical Haven', 'Ho Chi Minh City', 'District 2 (Thao Dien Expat Quarter)', NULL, NULL, 0, 2, 2, 2450, 'Located in Saigon’s premier leafy expatriate enclave. Walk to international bakeries, French bistros, wine boutiques, and world-class clinics (FV Hospital & Family Medical Practice).', '[]', '[]', '[{"id":"img_sg_1","url":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=80","caption":"Elegant open lounge with lush riverside balcony views","isPrimary":true},{"id":"img_sg_2","url":"https://images.unsplash.com/photo-1600566753376-12c8ab7fb75b?auto=format&fit=crop&w=1200&q=80","caption":"Executive chef kitchen with wine cooler and granite island","isPrimary":false}]', 0, 3, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
