-- 10. FAQS
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_01', 'How do visas work for retirees and long-term stays in Vietnam?', 'Vietnam provides straightforward tourist e-visas (up to 90 days with multiple entries) that can be seamlessly renewed with our concierge assistance. Furthermore, many retirees utilize business-sponsored visas, temporary residence cards (TRC), or investor options. Our accredited legal team coordinates all documentation, reminders, and border runs or in-country extensions for our residents.', 'Visa & Legal', 1, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_02', 'What is the quality of medical facilities and emergency care?', 'Vietnam’s major hubs host world-class JCI-accredited international hospitals including FV Hospital, Vinmec International Hospital, and Family Medical Practice. Medical staff speak fluent English and French, many having completed training in the US, Australia, or Europe. Out-of-pocket costs and international insurance premiums are typically 70% lower than in Western countries.', 'Healthcare', 2, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_03', 'How do I manage money, banking, and currency transfers?', 'You can comfortably use Western credit and debit cards (Visa/Mastercard) across Vietnam with zero hassle. In addition, our personal concierge assists in setting up local expat accounts, low-fee digital transfer channels (Wise, Remitly, bank wires), and automated bill clearance for utilities.', 'Finance', 3, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_04', 'What is included in the monthly living package?', 'All essential living costs: your fully furnished 2-bedroom executive residence, housekeeping three times a week, high-speed 100 Mbps fiber internet, utility allowance up to $150 USD/month, resort amenities (pool, clubhouse, gym), 24/7 security, and your dedicated English-speaking Personal Navigator.', 'Accommodation', 4, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_05', 'Can I bring my spouse, partner, or pets?', 'Absolutely. Our 2-bedroom residences are designed comfortably for couples. Vietnam is increasingly pet-friendly, with coastal parks and dedicated veterinarians. Our team assists with pet importation paperwork and airline transit guidelines.', 'General', 5, 1, '2026-10-31T03:26:22.264Z', '2026-10-27T14:41:54.124Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_06', 'How safe is Vietnam for international retirees and solo seniors?', 'Vietnam is widely recognized as one of the safest destinations in Southeast Asia. Violent crime is exceptionally rare, and senior residents frequently walk along coastal esplanades and city quarters late into the evening with complete peace of mind. Vietnamese culture holds immense respect and kindness for elders.', 'General', 6, 1, '2026-10-31T03:26:22.264Z', '2026-10-28T14:00:00.000Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_07', 'Can I drive in Vietnam, or is it better to use concierge transport?', 'International driver’s licenses can be converted into Vietnamese licenses with our team’s guidance. However, almost all of our residents prefer using on-demand private rides (Grab) or our dedicated Wanderer''s concierge shuttle, completely eliminating driving stress for only $3–$6 across town.', 'General', 7, 1, '2026-10-31T03:26:22.264Z', '2026-10-28T14:00:00.000Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_08', 'Which international health insurance policies are accepted by local hospitals?', 'Premier international insurers including Cigna Global, Allianz Care, Bupa, GeoBlue, and Aetna International have direct-billing agreements with top JCI-accredited hospitals in Vietnam (Vinmec, FV Hospital). Our team assists you in submitting claims and coordinating coverage.', 'Healthcare', 8, 1, '2026-10-31T03:26:22.264Z', '2026-10-28T14:00:00.000Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_09', 'Can I try a flexible month-to-month lease before committing to a full year?', 'Yes, flexibility is a cornerstone of Wanderer''s Journeys. You can begin with a 14-Day Exploratory Stay or 30-Day Living Trial, and smoothly transition to our Snowbird or 12-Month Retirement package without having to relocate or renegotiate leases.', 'Accommodation', 9, 1, '2026-10-31T03:26:22.264Z', '2026-10-28T14:00:00.000Z');
INSERT OR REPLACE INTO faqs (id, question, answer, category, display_order, is_published, created_at, updated_at) VALUES ('faq_10', 'How are US Social Security, Canadian CPP, or UK state pensions received in Vietnam?', 'You can keep your existing bank account in your home country and receive your pension deposits via direct deposit as usual. Using low-fee global debit cards or services like Wise, funds can be spent or transferred to local Vietnamese accounts in seconds at real interbank exchange rates with zero penalty.', 'Finance', 10, 1, '2026-10-31T03:26:22.264Z', '2026-10-28T14:00:00.000Z');

